def action_chunk(base, ranges, first_step, count, start_pitch=0.0, hip_bias=0.0, amplitude=0.45, center=0.0, period=50):
    rows = []
    for k in range(first_step, first_step+count):
        low, high = center-amplitude, center+amplitude
        if k < 10:
            pitch = start_pitch + (low-start_pitch)*(k+1)/10
        else:
            j = (k-10) % period
            phase = j / (period-1)
            pitch = (low + (high-low)*phase if ((k-10)//period)%2 == 0
                     else high - (high-low)*phase)
        row = base.copy()
        # Gradually firm the legs as the pelvis settles under the tool load.
        f = min(1.0, max(0.0, (k-150)/150.0))
        late = min(1.0, max(0.0, (k-500)/50.0))
        hip = -0.4 - 0.15*f - 0.3*late + hip_bias
        knee = 0.55 - 0.2*f
        ankle = -0.4 + 0.5*f
        support = {2:hip, 3:knee, 4:ankle, 7:hip, 8:knee, 9:ankle}
        for j, angle in support.items():
            lo, hi = ranges[j]
            row[j] = np.clip(2*(angle-lo)/(hi-lo)-1, -1, 1)
        for i in (11, 16):
            lo, hi = ranges[i]
            row[i] = np.clip(2*(pitch-lo)/(hi-lo)-1, -1, 1)

